  function pose(event,progress=.5){const names=['G','D','A','E'],index=names.indexOf(event?.string),open=[55,62,69,76][Math.max(0,index)],delta=Number.isFinite(event?.midi)?Math.max(0,Math.min(24,event.midi-open)):0,fraction=1-Math.pow(2,-delta/12),at=Math.max(0,Math.min(1,Number(progress)||0));return {bowX:(event?.bow==='up'?at:1-at)*90-45,bowY:0,stringIndex:index,fingerX:110+Math.max(0,index)*7+(-6+Math.max(0,index)*3)*fraction,fingerY:72+335*fraction,pressed:!!event&&event.finger>0};}
