    const words={prepare:['琴、琴弓、肩托、松香','Violin, bow, shoulder rest, rosin','楽器・弓・肩当て・松脂','Violine, Bogen, Schulterstütze, Kolophonium'],hold:['肩颈放松 · 左手轻扶 · 右手持弓','Relax shoulders · support gently · bow in right hand','肩の力を抜く・左手は軽く・右手で弓を持つ','Schultern locker · links leicht stützen · rechts streichen'],tune:['由低到高：G — D — A — E','Low to high: G — D — A — E','低い方から：G — D — A — E','Tief nach hoch: G — D — A — E'],open:['空弦不按指 · 弓与琴桥平行','Open string · bow parallel to the bridge','開放弦・弓は駒と平行','Leere Saite · Bogen parallel zum Steg'],fingers:['0 空弦 → 1 食指 → 2 中指 → 3 无名指','0 open → 1 index → 2 middle → 3 ring','0 開放弦 → 1 人差し指 → 2 中指 → 3 薬指','0 leer → 1 Zeige- → 2 Mittel- → 3 Ringfinger'],melody:['看当前弦、指号和弓向，再进入有声练习','Read string, finger and bow before the audio lesson','弦・指・弓を確認してから音声練習へ','Saite, Finger und Bogen lesen, dann mit Ton üben']};
